def seed_caravan_actions(apps, schema_editor):
    alias = schema_editor.connection.alias
    Location = apps.get_model("village", "VillageLocationDefinition")
    if Location.objects.using(alias).exists():
        Location.objects.using(alias).get_or_create(location_code="EMERGENCY_TRADE_POST", defaults={
            "display_name": "林边应急商队接货点", "center_anchor_code": "LOC_EMERGENCY_TRADE_POST",
            "location_type": "market", "bounds": {"center": [-94.98, 2.4783, 38.74]},
            "opening_hours": {"alwaysOpen": True}, "capacity": 3,
            "supported_action_types": ["MOVE", "IMPORT_GOODS", "EXPORT_GOODS"],
        })
    Fact = apps.get_model("village", "VillageStoryFact")
    Time = apps.get_model("game_time", "GlobalGameTimeState")
    minute = Time.objects.using(alias).filter(pk=1).values_list("world_minute", flat=True).first() or 0
    Fact.objects.using(alias).filter(store_limits_enabled=True).update(ration_limits_until_world_minute=(minute // 1440 + 3) * 1440)
    Profile = apps.get_model("village", "NpcProfile")
    for profile in Profile.objects.using(alias).filter(npc__agent_id="10015", npc__is_test_only=False):
        actions = list(profile.capabilities)
        for action in ("CONTACT_CARAVAN", "WITHDRAW_STORE_FUNDS", "SET_STORE_LIMITS", "START_DIALOGUE", "SPEAK"):
            if action not in actions:
                actions.append(action)
        profile.capabilities = actions
        profile.save(update_fields=["capabilities"])
    Duration = apps.get_model("village", "VillageActionDurationConfig")
    for name, duration in {"IMPORT_GOODS": 10, "EXPORT_GOODS": 10, "CONTACT_CARAVAN": 1,
                           "WITHDRAW_STORE_FUNDS": 1, "SET_STORE_LIMITS": 1}.items():
        Duration.objects.using(alias).update_or_create(action_name=name, defaults={"duration_minutes": duration})


